import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: size 기본 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

// 가정: post에 부서·개인 대상 컬럼이 없어 공개범위를 작성자 기준으로 판단한다.
// ALL은 모두, DEPARTMENT는 작성자와 같은 부서의 임직원, INDIVIDUAL은 작성자 본인에게만 보인다.
const VISIBLE_WHERE =
  ' FROM post p' +
  ' JOIN employee a ON a.employee_id = p.author_id' +
  ' WHERE (' +
  "   p.visibility_scope = 'ALL'" +
  "   OR (p.visibility_scope = 'DEPARTMENT' AND a.department_id IS NOT NULL" +
  '       AND a.department_id = (SELECT e.department_id FROM employee e WHERE e.employee_id = CAST(:userId AS bigint)))' +
  '   OR p.author_id = CAST(:userId AS bigint)' +
  ' )' +
  ' AND (CAST(:category AS text) IS NULL OR p.category = CAST(:category AS text))' +
  ' AND (CAST(:postType AS text) IS NULL OR p.post_type = CAST(:postType AS text))' +
  " AND (CAST(:keyword AS text) IS NULL OR p.title ILIKE '%' || CAST(:keyword AS text) || '%')";

@Controller('api/v1')
export class FnSfr03403Controller {
  @Get('/posts')
  async listPosts(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);

    const category = typeof query['category'] === 'string' && query['category'] !== '' ? query['category'] : null;
    const postType = typeof query['postType'] === 'string' && query['postType'] !== '' ? query['postType'] : null;
    const keyword = typeof query['keyword'] === 'string' && query['keyword'] !== '' ? query['keyword'] : null;
    if (postType !== null && postType !== 'NOTICE' && postType !== 'POST') {
      throw new ApiError(400, 'VALIDATION_FAILED', '구분은 NOTICE 또는 POST여야 합니다.');
    }
    if (category !== null && category.length > 100) {
      throw new ApiError(400, 'VALIDATION_FAILED', '분류는 100자 이하여야 합니다.');
    }

    const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const size = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);

    return transaction(async (db) => {
      const filter = { userId: user.id, category, postType, keyword };
      const items = await db.query(
        'SELECT p.post_id AS "postId", p.post_type AS "postType", p.category AS "category",' +
          ' p.title AS "title", p.author_id AS "authorId", p.created_at AS "createdAt",' +
          ' p.pin_start_date AS "pinStartDate", p.pin_end_date AS "pinEndDate"' +
          VISIBLE_WHERE +
          ' ORDER BY (p.pin_start_date IS NOT NULL AND p.pin_start_date <= current_date' +
          '   AND (p.pin_end_date IS NULL OR p.pin_end_date >= current_date)) DESC,' +
          ' p.created_at DESC, p.post_id DESC' +
          ' LIMIT CAST(:limit AS bigint) OFFSET CAST(:offset AS bigint)',
        { ...filter, limit, offset: page * limit },
      );
      const counted = await db.query('SELECT COUNT(*) AS "total"' + VISIBLE_WHERE, filter);
      const total = counted.length > 0 ? Number(counted[0]['total']) : 0;
      return { items, page, size: limit, total };
    });
  }
}

