import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Field,
  TextInput,
  Select,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr03403Page({ role, notify }: PageProps) {
  const [category, setCategory] = useState('');
  const [postType, setPostType] = useState('');
  const [keyword, setKeyword] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);

  const list = useData<Page>(
    () => call<Page>('GET', '/posts', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );
  const recent = useData<Page>(
    () => call<Page>('GET', '/posts', role, undefined, { postType: 'NOTICE', page: 0, size: 5 }),
    [role],
  );

  const search = () => {
    setPage(0);
    setApplied({ category, postType, keyword });
  };
  const reset = () => {
    setCategory('');
    setPostType('');
    setKeyword('');
    setPage(0);
    setApplied({});
  };

  const typeOptions: [string, string][] = [
    ['NOTICE', '공지사항'],
    ['POST', '게시물'],
  ];

  const columns = [
    { key: 'postType', label: '구분', render: (r: Row) => <Badge value={r.postType === 'NOTICE' ? '공지사항' : '게시물'} /> },
    { key: 'category', label: '분류' },
    { key: 'title', label: '제목' },
    { key: 'authorId', label: '작성자', render: (r: Row) => <RefName table="employee" role={role} value={r.authorId} /> },
    { key: 'createdAt', label: '생성 일시', render: (r: Row) => <DateText value={r.createdAt} time /> },
    {
      key: 'pinStartDate',
      label: '상단 고정 기간',
      render: (r: Row) =>
        r.pinStartDate ? (
          <span>
            <DateText value={r.pinStartDate} /> ~ <DateText value={r.pinEndDate} />
          </span>
        ) : (
          <span>-</span>
        ),
    },
  ];

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>분류별 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="분류">
            <TextInput value={category} onChange={setCategory} />
          </Field>
          <Field label="구분">
            <Select value={postType} onChange={setPostType} options={typeOptions} placeholder="전체" />
          </Field>
          <Field label="제목 등 검색어">
            <TextInput value={keyword} onChange={setKeyword} />
          </Field>
        </Filters>
        <Band total={list.data?.total} />
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          columns={columns}
          rows={list.data?.items ?? []}
          onRowClick={(r) => setSelected(r)}
          empty="조회 조건에 해당하는 공지·게시물이 없습니다."
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>최근 공지사항</h2>
        {recent.error ? <ErrorText text={recent.error} /> : null}
        <DataTable
          columns={[
            { key: 'title', label: '제목' },
            { key: 'createdAt', label: '등록일', render: (r: Row) => <DateText value={r.createdAt} /> },
          ]}
          rows={recent.data?.items ?? []}
          onRowClick={(r) => setSelected(r)}
          empty="최근 공지사항이 없습니다."
        />
      </section>
      {selected ? (
        <Drawer title="공지·게시물 정보" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['공지·게시물 ID', String(selected.postId)],
              ['구분', <Badge value={selected.postType === 'NOTICE' ? '공지사항' : '게시물'} />],
              ['분류', String(selected.category ?? '-')],
              ['제목', String(selected.title ?? '')],
              ['작성자', <RefName table="employee" role={role} value={selected.authorId} />],
              ['생성 일시', <DateText value={selected.createdAt} time />],
              ['상단 고정 시작일', <DateText value={selected.pinStartDate} />],
              ['상단 고정 종료일', <DateText value={selected.pinEndDate} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
